using System.IO;
using System.Threading;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using RAWSelectionAssistant.Core.Models;
using RAWSelectionAssistant.Services;

namespace RAWSelectionAssistant.WpfTests;

[TestClass]
public sealed class Version230StageDColorWpfTests
{
    [TestMethod] public Task CpuPreview_OneDimensionalProcessesProxyWithoutChangingSource() => RunSta(async () => { var source = Solid(2, 1, 0, 0, 0); var before = Pixels(source); var definition = new LutDefinition(null, LutKind.OneDimensional, 2, new(0,0,0), new(1,1,1), [new(1,0,0),new(1,0,0)]); var result = await new CpuLutPreviewService().RenderAsync(source, definition, 1, null); Assert.AreEqual((byte)255, Pixels(result.Image)[2]); CollectionAssert.AreEqual(before, Pixels(source)); });
    [TestMethod] public Task CpuPreview_ThreeDimensionalProcessesProxy() => RunSta(async () => { var source = Solid(1, 1, 20, 40, 60); var definition = new LutDefinition(null, LutKind.ThreeDimensional, 2, new(0,0,0), new(1,1,1), Enumerable.Repeat(new LutRgb(0,1,0),8).ToArray()); var result = await new CpuLutPreviewService().RenderAsync(source, definition, 1, null); Assert.AreEqual((byte)255, Pixels(result.Image)[1]); });
    [TestMethod] public Task CpuPreview_StrengthZeroMatchesSource() => RunSta(async () => { var source = Solid(1,1,30,40,50); var definition = new LutDefinition(null,LutKind.OneDimensional,2,new(0,0,0),new(1,1,1),[new(1,1,1),new(1,1,1)]); var result=await new CpuLutPreviewService().RenderAsync(source,definition,0,null); CollectionAssert.AreEqual(Pixels(source),Pixels(result.Image)); });
    [TestMethod] public Task CpuPreview_HonorsCancellation() => RunSta(async () => { using var cancel=new CancellationTokenSource(); cancel.Cancel(); var definition=new LutDefinition(null,LutKind.OneDimensional,2,new(0,0,0),new(1,1,1),[new(0,0,0),new(1,1,1)]); await Assert.ThrowsExactlyAsync<TaskCanceledException>(()=>new CpuLutPreviewService().RenderAsync(Solid(20,20,1,2,3),definition,1,null,cancel.Token)); });
    [TestMethod] public Task CpuPreview_InvalidIccFallsBackSrgb() => RunSta(async () => { var source=Solid(1,1,1,2,3); var definition=new LutDefinition(null,LutKind.OneDimensional,2,new(0,0,0),new(1,1,1),[new(0,0,0),new(1,1,1)]); var profile=new DisplayColorProfile("key","display","device",Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".icc"),"missing",DisplayProfileStatus.Missing,false,DateTimeOffset.UtcNow,"sRGB"); var result=await new CpuLutPreviewService().RenderAsync(source,definition,1,profile); Assert.IsTrue(result.UsedFallback); StringAssert.Contains(result.StatusText,"sRGB"); });
    [TestMethod] public void ColorConversion_MissingProfileReturnsSameImage() { var source=Solid(1,1,1,2,3); var profile=new DisplayColorProfile("key","display","device","missing.icc","missing",DisplayProfileStatus.Missing,false,DateTimeOffset.UtcNow,"sRGB"); var result=new WpfColorConversionService().ConvertToDisplay(source,profile,out var fallback); Assert.IsTrue(fallback); Assert.AreSame(source,result); }
    [TestMethod] public async Task Cache_UsesOpaqueKeyAndDoesNotExposePaths() { using var temp=new TempDirectory(); var cache=new LutPreviewCacheService(temp.Path); var key=cache.CreateOpaqueKey(new(Guid.NewGuid(),"proxy","lut",LutInputInterpretation.Unknown,50,"display","icc",1)); Assert.HasCount(64,key); Assert.IsTrue(key.All(Uri.IsHexDigit)); Assert.DoesNotContain("proxy",key,StringComparison.Ordinal); }
    [TestMethod] public async Task Cache_StoresAndResolvesValidPng() { using var temp=new TempDirectory(); var cache=new LutPreviewCacheService(temp.Path); var key=new string('a',64); using var png=LutBitmapEncoding.EncodePng(Solid(2,2,1,2,3)); await cache.StoreAsync(key,png); Assert.IsNotNull(cache.Resolve(key)); }
    [TestMethod] public async Task Cache_CorruptFileIsRejectedAndRebuildable() { using var temp=new TempDirectory(); var key=new string('b',64); File.WriteAllBytes(Path.Combine(temp.Path,key+".png"),[1,2,3]); var cache=new LutPreviewCacheService(temp.Path); Assert.IsNull(cache.Resolve(key)); using var png=LutBitmapEncoding.EncodePng(Solid(1,1,1,2,3)); await cache.StoreAsync(key,png); Assert.IsNotNull(cache.Resolve(key)); }
    [TestMethod] public async Task Cache_LruTrimsOldest() { using var temp=new TempDirectory(); var cache=new LutPreviewCacheService(temp.Path,300); for(var index=0;index<3;index++){ using var png=LutBitmapEncoding.EncodePng(Solid(20,20,(byte)index,2,3)); await cache.StoreAsync(new string((char)('a'+index),64),png); } Assert.IsLessThanOrEqualTo(300,new DirectoryInfo(temp.Path).EnumerateFiles("*.png").Sum(file=>file.Length)); }
    [TestMethod] public async Task Cache_InvalidationNeverTouchesOutsideRoot() { using var temp=new TempDirectory(); var outside=Path.Combine(Path.GetTempPath(),"PixelTartOutside-"+Guid.NewGuid()+".txt"); await File.WriteAllTextAsync(outside,"safe"); try { await new LutPreviewCacheService(temp.Path).InvalidateAsync(_=>true); Assert.IsTrue(File.Exists(outside)); } finally { File.Delete(outside); } }
    [TestMethod] public void ClientMonitorXaml_DefaultsHidePrivateMetadata() { var xaml=Text("src/RAWSelectionAssistant/Views/ClientMonitorWindow.xaml"); Assert.DoesNotContain("SourcePath",xaml,StringComparison.Ordinal); Assert.DoesNotContain("FileName",xaml,StringComparison.Ordinal); Assert.DoesNotContain("PhotographerNote",xaml,StringComparison.Ordinal); Assert.DoesNotContain("CameraSerial",xaml,StringComparison.Ordinal); }
    [TestMethod] public void ClientMonitorXaml_HasNoFileOperations() { var text=Text("src/RAWSelectionAssistant/Views/ClientMonitorWindow.xaml")+Text("src/RAWSelectionAssistant/Views/ClientMonitorWindow.xaml.cs"); foreach(var forbidden in new[]{"删除","移动","复制","打开所在位置","输出目录","工具箱","数据库管理","File.Delete","File.Move"}) Assert.DoesNotContain(forbidden,text,StringComparison.OrdinalIgnoreCase); }
    [TestMethod] public void ClientMonitorXaml_HasFavoriteAndNoteAccessibility() { var xaml=Text("src/RAWSelectionAssistant/Views/ClientMonitorWindow.xaml"); StringAssert.Contains(xaml,"AutomationProperties.Name=\"客户收藏按钮\""); StringAssert.Contains(xaml,"AutomationProperties.Name=\"客户备注输入框\""); }
