    [TestMethod] public void TetherWorkspace_HasLutImportSearchFavoriteDefaultsAndRelocation() { var text=TetherText(); foreach(var token in new[]{"导入 .cube","搜索LUT","收藏LUT","会话默认","项目默认","重新验证","重新定位","移除引用"}) StringAssert.Contains(text,token); }
