    [TestMethod] public void TetherWorkspace_HasInputSpaceUnknownWarning() { var text=TetherText(); StringAssert.Contains(text,"输入色彩空间未知"); StringAssert.Contains(text,"不保证色彩准确"); StringAssert.Contains(text,"仅用于现场监看参考"); }
    [TestMethod] public void TetherWorkspace_HasPerDisplayIccAndDisclaimer() { var text=TetherText(); StringAssert.Contains(text,"ICC 与客户屏"); StringAssert.Contains(text,"软件不能替代显示器校准"); StringAssert.Contains(text,"回退sRGB"); }
