    [TestMethod] public void TetherWorkspace_HasDefaultPrivacyToggles() { var text=TetherText(); foreach(var token in new[]{"简化文件编号（默认关闭）","拍摄参数摘要（默认关闭）","显示星级（默认关闭）","允许收藏和备注"}) StringAssert.Contains(text,token); }
    [TestMethod] public void TopologyUsesStableKeyAndNotDisplayIndex() { var source=Text("src/RAWSelectionAssistant/Services/WindowsDisplayServices.cs"); StringAssert.Contains(source,"DisplayStableKey.Create"); Assert.DoesNotContain("显示器1",source,StringComparison.Ordinal); Assert.DoesNotContain("显示器2",source,StringComparison.Ordinal); }
