    [TestMethod] public void ClientNotesDoNotEnterLogs() { var source=Text("src/RAWSelectionAssistant/ViewModels/TetherColorViewModel.cs")+Text("src/RAWSelectionAssistant.Core/Services/Tethering/TetherMonitoringServices.cs"); Assert.DoesNotContain("ClientNote}",source,StringComparison.Ordinal); Assert.DoesNotContain("PhotographerNote}",source,StringComparison.Ordinal); }
    [TestMethod] public void NoGpuOrVendorSdkIntroduced() { var source=Text("src/RAWSelectionAssistant/ViewModels/TetherColorViewModel.cs")+Text("src/RAWSelectionAssistant/Services/LutPreviewServices.cs"); foreach(var forbidden in new[]{"Direct3D","D3D11","CUDA","Edsdk","CameraRemoteSDK","MAID"}) Assert.DoesNotContain(forbidden,source,StringComparison.OrdinalIgnoreCase); }
    [TestMethod] public void NoLocalhostAndReleaseProviderNoneRemain() { var source=Text("src/RAWSelectionAssistant/ViewModels/TetherColorViewModel.cs")+Text("src/RAWSelectionAssistant/Services/WindowsDisplayServices.cs"); Assert.DoesNotContain("localhost",source,StringComparison.OrdinalIgnoreCase); StringAssert.Contains(Text("src/RAWSelectionAssistant/appsettings.license.json"),"\"Provider\": \"None\""); }

    private static BitmapSource Solid(int width,int height,byte blue,byte green,byte red){var pixels=new byte[width*height*4];for(var i=0;i<pixels.Length;i+=4){pixels[i]=blue;pixels[i+1]=green;pixels[i+2]=red;pixels[i+3]=255;}var bitmap=BitmapSource.Create(width,height,96,96,PixelFormats.Bgra32,null,pixels,width*4);bitmap.Freeze();return bitmap;}
    private static byte[] Pixels(BitmapSource source){var converted=source.Format==PixelFormats.Bgra32?source:new FormatConvertedBitmap(source,PixelFormats.Bgra32,null,0);var bytes=new byte[converted.PixelWidth*converted.PixelHeight*4];converted.CopyPixels(bytes,converted.PixelWidth*4,0);return bytes;}
    private static string TetherText()=>Text("src/RAWSelectionAssistant/Views/TetherCaptureView.xaml")+Text("src/RAWSelectionAssistant/ViewModels/TetherColorViewModel.cs");
    private static string Text(string relative){for(var directory=new DirectoryInfo(AppContext.BaseDirectory);directory is not null;directory=directory.Parent)if(File.Exists(Path.Combine(directory.FullName,"RAWSelectionAssistant.sln")))return File.ReadAllText(Path.Combine(directory.FullName,relative.Replace('/',Path.DirectorySeparatorChar)));throw new DirectoryNotFoundException();}
    private static Task RunSta(Func<Task> action){var completion=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var thread=new Thread(async()=>{try{await action();completion.SetResult();}catch(Exception ex){completion.SetException(ex);}});thread.SetApartmentState(ApartmentState.STA);thread.Start();return completion.Task;}
    private sealed class TempDirectory:IDisposable{public TempDirectory(){Path=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"PixelTart.StageDWpf",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path);}public string Path{get;}public void Dispose(){try{Directory.Delete(Path,true);}catch{}}}
}
